function mapOf(o) {
  return Object.keys(o).join(',');
}
function icState(distinct) {
  if (distinct <= 1) return 'monomorphic';
  if (distinct <= 4) return 'polymorphic';
  return 'megamorphic';
}

// One load site sees this stream of objects (different shapes mixed in).
const stream = [
  { value: 1 },
  { value: 2 },
  { value: 3, tag: 'x' },
  { value: 4, tag: 'y', extra: 1 },
  { tag: 'z', value: 5 },         // reversed order -> distinct map
  { value: 6, note: true },
];

const seen = new Set();
for (const o of stream) seen.add(mapOf(o));
const distinct = seen.size;
console.log('distinctMaps=' + distinct + ' state=' + icState(distinct));

