tasks.starter:
// IC ladder: 1 -> monomorphic, 2..4 -> polymorphic, 5+ -> megamorphic.
function icState(distinctMaps) {
  if (distinctMaps <= 1) return 'monomorphic';
  if (distinctMaps <= 5) return 'polymorphic';
  return 'megamorphic';
}

tasks.verify:
const cases = [[1,'monomorphic'],[4,'polymorphic'],[5,'megamorphic'],[6,'megamorphic']];
let ok = true, bad = '';
for (const [n, want] of cases) { const got = icState(n); if (got !== want) { ok = false; bad = n + '=>' + got; break; } }
console.log(ok ? 'PASS' : 'FAIL ' + bad);
